// CS427: continuous skin tone via a slider. tone 0 = lightest .. 100 = darkest, interpolated across the
// curated SKINS ramp so every value is a natural tone. Old saves (look.skin id) map to their ramp position.
function skinRampHex(t){ const stops=SKINS.map(s=>s.m), n=stops.length-1;
  const p=Math.max(0,Math.min(1,(+t||0)/100))*n, i=Math.min(n-1,Math.floor(p)), f=p-i;
  const A=avHexRgb(stops[i]), B=avHexRgb(stops[i+1]);
  const c=k=>Math.round(A[k]+(B[k]-A[k])*f).toString(16).padStart(2,'0');
  return '#'+c('r')+c('g')+c('b'); }
function skinToneOf(L){ L=L||S.look||DEFLOOK; if(L.skinTone!=null) return +L.skinTone;
  const i=SKINS.findIndex(s=>s.id===L.skin); return i>=0 ? Math.round(i/(SKINS.length-1)*100) : 29; }
