function clubSetTag(look){ try{ const c=CLUBS_BY[((look||S.look||{}).club)||'']; return (c&&c.tag)||''; }catch(e){ return ''; } }
function h2hUnitClubTag(u){ try{ const m=u&&u.members&&u.members[0]; return clubSetTag(m&&m.draft&&m.draft.look); }catch(e){ return ''; } }
